mapper.select:
SELECT sigungu.region_code, sigungu.region_name, statistics.damage_house_count, #{baseDate} AS base_date FROM regions sido
INNER JOIN regions sigungu ON sigungu.parent_region_id = sido.region_id AND sigungu.region_level = 'SIGUNGU'
LEFT JOIN fraud_damage_statistics statistics ON statistics.region_id = sigungu.region_id AND statistics.base_date = #{baseDate}
WHERE sido.region_level = 'SIDO' AND sido.region_code = #{parentRegionCode}
ORDER BY sigungu.region_code
